using System.IO;
using System.Text.Json;
using System.Windows.Controls;
using PhotoTrail.Windows;

static partial class Program
{
 static async Task PostFaultChecks(){
  await ImportDone();var tool=(ExifToolClient)M3Call("Tool")!;var seed=Control<ListBox>("Photos").Items.Cast<object>().Select(Doc).First(d=>d.FileType=="JPEG");
  async Task<PhotoDocument> Fresh(string name){var path=Path.Combine(folder,name+".jpg");File.Copy(seed.FilePath,path);var doc=await PhotoDocument.LoadAsync(tool,path,inspect:true);doc.SetDraft(new Dictionary<string,string>{{"XMP-dc:Title","fault draft"}});return doc;}
  var doc=await Fresh("occupied");var output=Path.Combine(folder,"occupied-output");Directory.CreateDirectory(output);var target=Path.Combine(output,Path.GetFileName(doc.FilePath));File.Copy(seed.FilePath,target);var hash=await PhotoDocument.HashAsync(target);
  await ExpectFailure(()=>MetadataCopy.SaveAsync(tool,doc,output),"M10-real-existing-target-refused");Check(await PhotoDocument.HashAsync(target)==hash&&doc.Draft.Count==1,"M10-existing-target-and-draft-preserved");
  doc=await Fresh("read-only");File.SetAttributes(doc.FilePath,File.GetAttributes(doc.FilePath)|FileAttributes.ReadOnly);try{bool refused=false;try{SavePlan.Prepare([doc],SaveMode.Inplace,SaveScope.All,"",[doc]);}catch(IOException){refused=true;}Check(refused&&doc.Draft.Count==1,"M10-real-read-only-inplace-rejected-before-write");}finally{File.SetAttributes(doc.FilePath,FileAttributes.Normal);}
  doc=await Fresh("locked");output=Path.Combine(folder,"locked-output");Directory.CreateDirectory(output);using(var locked=new FileStream(doc.FilePath,FileMode.Open,FileAccess.ReadWrite,FileShare.None)){await ExpectFailure(()=>MetadataCopy.SaveAsync(tool,doc,output),"M10-real-source-sharing-lock-refused");}Check(!Directory.EnumerateFileSystemEntries(output).Any()&&doc.Draft.Count==1,"M10-source-lock-leaves-no-output-and-keeps-draft");
  doc=await Fresh("changed");var plan=await RenamePlan.BuildTargetsAsync([(doc.FilePath,"changed-new.jpg")]);File.AppendAllText(doc.FilePath,"controlled source change");await ExpectFailure(()=>RenameExecutor.ExecuteAsync(plan,Path.Combine(folder,"changed-journal")),"M10-real-source-change-after-freeze-refused");Check(File.Exists(doc.FilePath)&&!File.Exists(Path.Combine(folder,"changed-new.jpg")),"M10-source-change-not-partly-renamed");
  doc=await Fresh("cancel");output=Path.Combine(folder,"cancel-output");Directory.CreateDirectory(output);using(var cancel=new CancellationTokenSource()){cancel.Cancel();bool canceled=false;try{await MetadataCopy.SaveAsync(tool,doc,output,cancel.Token);}catch(OperationCanceledException){canceled=true;}Check(canceled&&doc.Draft.Count==1&&!Directory.EnumerateFileSystemEntries(output).Any(),"M10-controlled-cancel-preserves-draft-and-source");}
  foreach(var fault in new[]{"--fake-error","--fake-disk-full"}){doc=await Fresh(fault.TrimStart('-'));output=Path.Combine(folder,fault.TrimStart('-')+"-output");Directory.CreateDirectory(output);var failing=new ExifToolClient(Environment.GetEnvironmentVariable("PHOTOTRAIL_FAULT_TOOL")??throw new Exception("Missing isolated fault tool"),fault);await ExpectFailure(()=>MetadataCopy.SaveAsync(failing,doc,output),"M10-injected-tool-failure-"+fault);Check(!Directory.EnumerateFileSystemEntries(output).Any()&&await PhotoDocument.HashAsync(doc.FilePath)==doc.SourceHash&&doc.Draft.Count==1,"M10-injected-failure-no-output-source-and-draft-preserved-"+fault);}
  doc=await Fresh("unknown");var backup=Path.Combine(folder,"unknown-backup");Directory.CreateDirectory(backup);var item=SavePlan.Prepare([doc],SaveMode.Inplace,SaveScope.All,"",[doc]).Items.Single();var proof=await VerifiedMetadataDates.CreateAsync(doc.Draft,CancellationToken.None);var saved=await InplaceSave.SaveAsync(tool,item,backup,proof,CancellationToken.None);Check(saved.Document is not null,"M10-unknown-setup-real-TxF-write-and-readback");var record=InplaceHistory.ReadAll().Single(r=>r.Id==saved.RecordId);InplaceHistory.Append(record with{Phase="unknown",Detail="test simulation: UI adoption interrupted after readback"});
  PlanFailure(()=>SavePlan.Prepare([doc],SaveMode.Inplace,SaveScope.All,"",[doc]),"M10-simulated-postwrite-UI-failure-persists-unknown-and-blocks-retry");Check(File.Exists(record.Backup)&&await PhotoDocument.HashAsync(record.Backup)==doc.SourceHash&&doc.Draft.Count==1,"M10-unknown-keeps-unique-original-backup-and-draft");
  await InplaceHistory.RestoreAsync(tool,record,CancellationToken.None);SelectRecovery(record.Id);Action("CheckInplaceRecord");await BatchWait();Check(await PhotoDocument.HashAsync(doc.FilePath)==doc.SourceHash&&InplaceHistory.Read(InplaceHistory.PathFor(record.Id)).Phase=="restored","M10-explicit-unknown-record-restores-original");
  File.WriteAllText(Path.Combine(folder,"postfault-results.json"),JsonSerializer.Serialize(new{buildSha=Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(File.ReadAllBytes(typeof(MainWindow).Assembly.Location))),simulation="cancel token and post-write adoption failure; target/locks/read-only/source-change/TxF are real filesystem",evidence},new JsonSerializerOptions{WriteIndented=true}));
 }
 static async Task PostCrashChecks(){
  await ImportDone();var tool=(ExifToolClient)M3Call("Tool")!;var doc=Control<ListBox>("Photos").Items.Cast<object>().Select(Doc).First();doc.SetDraft(new Dictionary<string,string>{{"XMP-dc:Title","process-interruption-test"}});var backup=Path.Combine(folder,"crash-backup");Directory.CreateDirectory(backup);var item=SavePlan.Prepare([doc],SaveMode.Inplace,SaveScope.All,"",[doc]).Items.Single();var saved=await InplaceSave.SaveAsync(tool,item,backup,await VerifiedMetadataDates.CreateAsync(doc.Draft,CancellationToken.None),CancellationToken.None);Check(saved.Document is not null,"M10-crash-setup-real-disk-readback-before-UI-adoption");
  File.WriteAllText(Path.Combine(folder,"crash-setup.json"),JsonSerializer.Serialize(new{saved.RecordId,originalHash=doc.SourceHash,savedHash=saved.Hash,buildSha=Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(File.ReadAllBytes(typeof(MainWindow).Assembly.Location)))}));Environment.Exit(91);
 }
 static async Task PostRestartChecks(){
  await ImportDone();var record=InplaceHistory.ReadAll().Single(InplaceHistory.Pending);Check(record.Phase=="readback"&&await PhotoDocument.HashAsync(record.Target)==record.NewHash,"M10-real-process-interruption-left-new-disk-and-pending-record");bool blocked=false;try{InplaceHistory.RequireClear([record.Target]);}catch(IOException){blocked=true;}Check(blocked,"M10-restart-blocks-pending-target");SelectRecovery(record.Id);Action("CheckInplaceRecord");await BatchWait();Check(InplaceHistory.Read(InplaceHistory.PathFor(record.Id)).Phase=="saved","M10-restart-explicit-independent-readback-adopts-known-result");SelectRecovery(record.Id);Action("RestoreInplaceRecord");await BatchWait();Check(InplaceHistory.Read(InplaceHistory.PathFor(record.Id)).Phase=="restored"&&await PhotoDocument.HashAsync(record.Target)==record.OriginalHash,"M10-restart-explicit-record-restore-original-bytes");
  File.WriteAllText(Path.Combine(folder,"post-restart-results.json"),JsonSerializer.Serialize(new{buildSha=Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(File.ReadAllBytes(typeof(MainWindow).Assembly.Location))),evidence},new JsonSerializerOptions{WriteIndented=true}));
 }
}
